contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target, uint _value, bytes memory _data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value);
        require(_target != address(c));
        require(_target != address(this));

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool targetWouldSucceed;
        c.sendMoney(_target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            targetWouldSucceed = false;
        } else {
            targetWouldSucceed = true;
        }

        bool reverted = !targetWouldSucceed;
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            reverted == (beforeBalance < _value)
            && (reverted
                ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                : (afterBalance == beforeBalance - _value && afterDeposits == beforeDeposits))
        );
    }

    receive() external payable {}
}

