    function _run(address _target, uint256 _value, bytes memory _data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        vm.assume(_target != address(c));
        vm.assume(_target != address(this));
        uint beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool targetWouldSucceed;
        try c.sendMoney(_target, _value, _data) {
            targetWouldSucceed = true;
        } catch {
            targetWouldSucceed = false;
        }
